const invoices = $input.all();
const today = new Date();
const results = [];

for (const invoice of invoices) {
  const data = invoice.json;

  // 1. Safely extract and clean data fields
  const rawDueDate = data['Due date'];
  const rawIssueDate = data['Issue date'];
  const rawLastReminder = data['Last reminder sent'];

  // 2. Convert to valid Date objects or null
  const dueDate = rawDueDate ? new Date(rawDueDate) : null;
  const issueDate = rawIssueDate ? new Date(rawIssueDate) : null;

  // Handle empty strings "" or whitespace gracefully for last reminder
  const lastReminder = (rawLastReminder && String(rawLastReminder).trim() !== '') 
    ? new Date(rawLastReminder) 
    : null;

  // 3. FOOLPROOF GUARD: Skip or default if critical due date is invalid
  if (!dueDate || isNaN(dueDate.getTime())) {
    // If there's no valid due date, we skip reminder logic for this row to prevent crashes
    continue; 
  }

  // 4. Calculate days overdue safely
  const daysOverdue = Math.floor((today - dueDate) / (1000 * 60 * 60 * 24));

  // 5. Calculate days since last reminder safely
  let daysSinceReminder = 999;
  if (lastReminder && !isNaN(lastReminder.getTime())) {
    daysSinceReminder = Math.floor((today - lastReminder) / (1000 * 60 * 60 * 24));
  }

  // 6. Determine reminder type and urgency
  let reminderType = '';
  let urgencyLevel = '';
  let shouldSendReminder = false;

  if (daysOverdue > 30 && daysSinceReminder >= 3) {
    reminderType = 'final_notice';
    urgencyLevel = 'critical';
    shouldSendReminder = true;
  } else if (daysOverdue > 14 && daysSinceReminder >= 5) {
    reminderType = 'second_reminder';
    urgencyLevel = 'high';
    shouldSendReminder = true;
  } else if (daysOverdue > 0 && daysSinceReminder >= 7) {
    reminderType = 'first_reminder';
    urgencyLevel = 'medium';
    shouldSendReminder = true;
  } else if (daysOverdue === 0) {
    reminderType = 'due_today';
    urgencyLevel = 'medium';
    shouldSendReminder = true;
  } else if (daysOverdue < 0 && daysOverdue >= -3 && !lastReminder) {
    reminderType = 'upcoming_reminder';
    urgencyLevel = 'low';
    shouldSendReminder = true;
  }

  // 7. Output results
  if (shouldSendReminder) {
    results.push({
      json: {
        ...data,
        daysOverdue,
        daysSinceReminder,
        reminderType,
        urgencyLevel,
        shouldSendReminder
      }
    });
  }
}

return results;

