parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // 1. Safe AI input capture
  let aiResponse = data.output || '';
  if (typeof aiResponse !== 'string') {
    aiResponse = String(aiResponse);
  }

  // Convert literal "\n" text strings to real line breaks
  aiResponse = aiResponse.replace(/\\n/g, '\n');

  // 2. Extract and strip out Subject
  const subjectMatch = aiResponse.match(/Subject:\s*(.+?)(?:\n|$)/i);

  // --- UPDATED FALLBACK TO USE INVOCIE ID ---
  const invoiceId = data['Invocie ID'] || data['Invoice number'] || 'N/A';
  const subject = subjectMatch ? subjectMatch[1].trim() : `Payment Reminder - Invoice ID ${invoiceId}`;

  let mainBody = aiResponse.replace(/Subject:\s*.+?(?:\n|$)/i, '').trim();
  if (!mainBody) { mainBody = aiResponse; }

  // 3. Clean up greeting formatting dynamically based on your Sheet input
  const clientName = data['Client name'] || 'Customer';
  const greetingRegex = new RegExp(`Dear\\s+${clientName},?`, 'i');
  mainBody = mainBody.replace(greetingRegex, `Dear ${clientName},`);

  // 4. Extract target data table variables safely
  const invoiceNum = data['Invoice number'] || 'N/A';
  const currency = data['Currency'] || '';
  const amount = data['Invoice amount'] || '0.00';
  const dueDate = data['Due date'] || 'N/A';
  const daysOverdue = parseInt(data['Days overdue'] || data.daysOverdue, 10);

  let statusText = 'Due Soon';
  let statusColor = '#f57c00';
  if (!isNaN(daysOverdue) && daysOverdue > 0) {
    statusText = `Overdue by ${daysOverdue} days`;
    statusColor = '#d32f2f';
  }

  // Build the clean HTML Table block
  const invoiceTable = `
  <div style="background-color: #f5f5f5; padding: 20px; border-radius: 8px; margin: 20px 0; max-width: 500px;">
    <h3 style="color: #333; margin-top: 0; font-family: Arial, sans-serif;">Invoice Details</h3>
    <table style="width: 100%; border-collapse: collapse; font-family: Arial, sans-serif; font-size: 14px;">
      <tr>
        <td style="padding: 8px 0; font-weight: bold; color: #555;">Invoice Number:</td>
        <td style="padding: 8px 0; text-align: right; color: #333;">${invoiceNum}</td>
      </tr>
      <tr>
        <td style="padding: 8px 0; font-weight: bold; color: #555;">Invoice ID:</td>
        <td style="padding: 8px 0; text-align: right; color: #333;">${invoiceId}</td>
      </tr>
      <tr>
        <td style="padding: 8px 0; font-weight: bold; color: #555;">Amount:</td>
        <td style="padding: 8px 0; text-align: right; color: #333; font-weight: bold;">${currency} ${amount}</td>
      </tr>
      <tr>
        <td style="padding: 8px 0; font-weight: bold; color: #555;">Due Date:</td>
        <td style="padding: 8px 0; text-align: right; color: #333;">${dueDate}</td>
      </tr>
      <tr>
        <td style="padding: 8px 0; font-weight: bold; color: #555;">Status:</td>
        <td style="padding: 8px 0; text-align: right; color: ${statusColor}; font-weight: bold;">${statusText}</td>
      </tr>
    </table>
  </div>
  `;

  // 5. REMOVE THE EXAMPLE LINES AND PLACEHOLDERS COMPLETELY
  mainBody = mainBody
    .replace(/\[Insert your preferred payment instructions[\s\S]*?\]/gi, '') // Strips bracket text
    .replace(/^.*\*Example:.*$/gm, '')                                       // Strips any line containing *Example:*
    .replace(/\n\s*\n\s*\n/g, '\n\n')                                        // Cleans up trailing blank space lines
    .trim();

  // 6. Split body up around the table insertion spot dynamically
  let introduction = `Dear ${clientName},`;
  let contentText = mainBody;

  if (mainBody.toLowerCase().startsWith(`dear ${clientName.toLowerCase()},`)) {
    contentText = mainBody.substring(`dear ${clientName},`.length).trim();
  }

  // Convert text paragraphs to HTML breaks safely
  let formattedContent = contentText
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n/g, '<br>');

  // Isolate sections dynamically to drop table in perfectly after instructions intro paragraph
  const splitPoints = formattedContent.split('<br><br>');
  const topSection = splitPoints.slice(0, 3).join('<br><br>');
  const bottomSection = splitPoints.slice(3).join('<br><br>');

  // 7. Assemble Final Email Layout
  const htmlBody = `
  <html>
    <body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;">
      <p style="margin-bottom: 20px;">${introduction}</p>
      <div>${topSection}</div>
      ${invoiceTable}
      <div>${bottomSection}</div>
      <div style="margin-top: 30px; padding-top: 20px; border-top: 1px solid #ddd; font-size: 12px; color: #666;">
        <p>This is an automated reminder. If you have already made this payment, please disregard this email.</p>
      </div>
    </body>
  </html>
  `;

  results.push({
    json: {
      ...data,
      emailSubject: subject,
      emailBody: htmlBody,
      emailBodyPlain: mainBody.replace(/<[^>]*>/g, '')
    }
  });
}

return results;

